mapper.select:
SELECT f.id, f.title, f.season, f.content, i.img_url, f.created_at, f.updated_at FROM festival f LEFT JOIN image i ON f.id = i.owner_id AND i.type = 'FESTIVAL' AND i.rep_img_yn = 'Y' WHERE f.deleted_at IS NULL
AND f.season = #{season}
ORDER BY created_at DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE  festival
    SET     title   = #{title},
            content = #{content},
            season  = #{season},
            updated_at = #{updatedAt}
    WHERE   id      = #{id}

UPDATE  image
    SET     img_url     = #{imgUrl}
    WHERE   owner_id    = #{id}
    AND     type        = 'FESTIVAL'

UPDATE  festival
SET     deleted_at = CURRENT_TIMESTAMP
WHERE   id = #{festivalId}
